window.CV_BASE64 = '';

window.downloadCVDirect = function(e) {
  if (e) {
    if (e.preventDefault) e.preventDefault();
    if (e.stopPropagation) e.stopPropagation();
  }
  var fileName = 'CV Carlos Eduardo Quijano Gonzalez.pdf';
  if (window.CV_BASE64) {
    try {
      var byteCharacters = atob(window.CV_BASE64);
      var byteNumbers = new Array(byteCharacters.length);
      for (var i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }
      var byteArray = new Uint8Array(byteNumbers);
      var blob = new Blob([byteArray], { type: 'application/octet-stream' });
      var blobUrl = window.URL.createObjectURL(blob);

      var tempLink = document.createElement('a');
      tempLink.style.display = 'none';
      tempLink.href = blobUrl;
      tempLink.setAttribute('download', fileName);
      document.body.appendChild(tempLink);
      tempLink.click();

      setTimeout(function() {
        if (document.body.contains(tempLink)) {
          document.body.removeChild(tempLink);
        }
        window.URL.revokeObjectURL(blobUrl);
      }, 500);
      return false;
    } catch (err) {
      console.error('Error al generar blob desde Base64:', err);
    }
  }

  if (window.location.protocol.startsWith('http')) {
    fetch('CV%20Carlos%20Eduardo%20Quijano%20Gonzalez.pdf')
      .then(function(res) { return res.blob(); })
      .then(function(blob) {
        var blobOctet = new Blob([blob], { type: 'application/octet-stream' });
        var blobUrl = window.URL.createObjectURL(blobOctet);
        var tempLink = document.createElement('a');
        tempLink.style.display = 'none';
        tempLink.href = blobUrl;
        tempLink.setAttribute('download', fileName);
        document.body.appendChild(tempLink);
        tempLink.click();
        setTimeout(function() {
          if (document.body.contains(tempLink)) {
            document.body.removeChild(tempLink);
          }
          window.URL.revokeObjectURL(blobUrl);
        }, 500);
      })
      .catch(function(err) {
        console.error(err);
      });
  }
  return false;
};
